import os
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PAGES=[("index","Brand"),("guidelines","Guidelines"),("palette","Palette"),("typography","Typography"),("icons","Icons"),("logos","Logos & app icons"),("screens","Screens"),("levels","Levels"),("characters","Characters"),("costumes","Costumes"),("vehicles","Vehicles"),("powerups","Power-ups"),("souvenirs","Souvenirs & perks"),("devices","Devices")]
def nav(cur):
    return '<nav><a class="brand" href="index.html"><img src="logos/wordmark_light.svg" alt="GIDI++" height="34"></a>'+"".join(f'<a href="{k}.html"{" class=on" if k==cur else ""}>{t}</a>' for k,t in PAGES)+'<small>Design system v1.0 · Oct 2026 · LANDSCAPE ONLY (RT-106)</small></nav>'
def page(k, body):
    t=dict(PAGES)[k]
    open(os.path.join(ROOT,f"{k}.html"),"w").write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gidi++ · {t}</title><link rel="stylesheet" href="css/site.css"><link rel="icon" href="logos/app/web/favicon.ico" sizes="any"><link rel="icon" type="image/png" href="logos/app/web/favicon-32.png"><link rel="apple-touch-icon" href="logos/app/web/apple-touch-icon.png"></head><body>{nav(k)}<main>{body}</main></body></html>')
def stub(title, items):
    return f'<h1>{title} <span class="badge">STUB, phase 2</span></h1><div class="stub"><b>Planned contents</b><ul>'+"".join(f"<li>{i}</li>" for i in items)+'</ul></div>'

page("index", '''<h1>Gidi++ brand</h1><p class="lead">Cross Lagos. Don't get jammed. A 3D (Unity URP, semi-real, perspective camera) curb-crossing game for Millennials and Gen Z. You play Baba Gidi (12+, <b>not</b> a kids' game). You lead a crowd across Lagos traffic, from Agege to the endless chaos of Ojuelegba.</p>
<div class="card"><h3>Pillars</h3><ul><li><b>Semi-real Lagos dusk-glass.</b> Grounded proportions and believable materials, pushed about 20% toward readability. Ink glass UI, warm gold, hairline edges.</li><li><b>Readable threats first.</b> Every danger is shown by colour <i>and</i> shape <i>and</i> motion (colour-blind safe).</li><li><b>Fair free-to-play.</b> Soft-currency power-ups (₦ Naira Chips), <b>1 continue per run</b>, cosmetics only for real money.</li><li><b>Proudly Lagos.</b> Real places and Pidgin/Yoruba flavour ("Eiya!", "Owa!", "Enter with your change!"), with fictional brands only.</li></ul></div>
<div class="card"><h3>Voice</h3><table><tr><th>Do</th><th>Don't</th></tr><tr><td>Pidgin-first, warm, street-smart: "Chai! Traffic don catch you…", "Oya, cross!", "We don reach!"</td><td>Internal or marketing copy ("Elegant continue")</td></tr><tr><td>Pidgin flavour that a first-timer can still understand from context</td><td>Mocking accents, kid-speak, real trademarks</td></tr></table></div>
<div class="card"><h3>Platform rule</h3><p><b>Landscape only</b> on every device (Kehinde, Oct 16, 2026, RT-106). Cars cross sideways, so landscape shows whole lanes. There are no portrait layouts.</p></div>
<h2>Sections</h2><div class="grid"><a class="card" style="text-decoration:none;color:inherit;margin:0" href="screens.html"><b>Screens</b><br><span class="small">Every screen, desktop + phone, with flow</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="levels.html"><b>Levels</b><br><span class="small">L1–L10 from LevelManager</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="characters.html"><b>Characters</b><br><span class="small">Baba Gidi, peds, Slay Queen, Agbada Man, LASTMA/KAI, hawkers</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="costumes.html"><b>Costumes</b><br><span class="small">Baba Gidi fits, 3D dusk renders</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="vehicles.html"><b>Vehicles</b><br><span class="small">Danfo, keke, taxi + okada, tanker, BRT, paint jobs</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="powerups.html"><b>Power-ups</b><br><span class="small">Pickups vs references + Owa!, Danfo Ride, Agbada Armour</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="palette.html"><b>Palette</b><br><span class="small">Swatches, hex, contrast</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="typography.html"><b>Typography</b><br><span class="small">Type scale</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="icons.html"><b>Icons</b><br><span class="small">SVG power-ups, HUD, warnings</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="logos.html"><b>Logos &amp; app icons</b><br><span class="small">Wordmark, iOS/Android/web</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="souvenirs.html"><b>Souvenirs &amp; perks</b><br><span class="small">Perks from code, souvenirs concept</span></a><a class="card" style="text-decoration:none;color:inherit;margin:0" href="devices.html"><b>Devices</b><br><span class="small">Safe areas, orientation lock</span></a></div>
<h2>Key screens</h2><div class="grid"><a href="screens.html#s-home"><img class="shot" src="exports/home-desktop.png" alt="Home"></a><a href="screens.html#s-shop"><img class="shot" src="exports/shop-desktop.png" alt="Base Camp"></a><a href="screens.html#s-hud"><img class="shot" src="exports/hud-desktop.png" alt="HUD"></a><a href="screens.html#s-gameover"><img class="shot" src="exports/gameover-desktop.png" alt="Game over"></a></div>''')

page("guidelines", '''<h1>Guidelines</h1><p class="lead">Rules every screen follows. The source is G-Prototype <code>docs/ui/ArtDirection_OnePager.md</code> and <code>UX_Flows_Sprint1.md</code>.</p>
<div class="card do"><h3>Layout</h3><ul><li><b>Landscape only.</b> Reference canvas 1920×1080, CanvasScaler matched on height.</li><li>Everything sits inside <code>Screen.safeArea</code>. Desktop margin 32 px. Phone (19.5:9, 2340×1080): notch inset 132 px, home indicator 63 px.</li><li>Minimum touch target <b>144 px = 48 dp</b>. Primary CTA 192 px tall.</li><li>Thumb zones: bottom-left (translucent PICK UP) and bottom-right (translucent 8-way d-pad, primary CTA). Pause and Settings top-right, where they need a deliberate reach.</li><li>In-run: camera and controls as in the current build (overlap of controls with lane ends accepted). See the <a href="screens.html#hud">HUD spec</a>.</li></ul></div>
<div class="card do"><h3>HUD</h3><ul><li>Stock order is always <b>GROUP → CHANGE → OWA!</b>, left to right.</li><li>Currency is always <b>₦</b> + amount (<code>₦12,450</code>), never "N".</li><li>Continue: <b>max 1 per run</b>. Cost: 100 chips at L1, 125 chips at L2+, or watch an ad (GidiEconomyTables).</li><li>Touch controls only on touch devices. No keyboard / "Space" hints on screen.</li></ul></div>
<div class="card do"><h3>Accessibility</h3><ul><li>Warning states pair colour with shape, icon and motion (see Palette).</li><li>Text contrast is WCAG AA or better on glass; graphics are at least 3:1.</li><li>Planned: colour-blind mode, text size S/M/L, reduce motion, haptics toggle.</li></ul></div>
<div class="card dont"><h3>Don't</h3><ul><li>No portrait layouts. No kid-style bubbly UI. No real brands.</li><li>No invented economy numbers. Prices, caps and unlocks per vision doc (Kehinde, Oct 16); game-side changes in G-Prototype PR #51.</li><li>Never rely on colour alone. Don't move controls away from the build positions without sign-off.</li></ul></div>''')

